validate_doc_update:
function(newDoc, oldDoc, userCtx, secObj) {
  if (newDoc._deleted) return;
  var canonicalTypes = {
    "account": true,
    "location": true,
    "employee": true,
    "visit": true,
    "visit_gap": true,
    "opportunity": true,
    "shift_report": true,
    "journal": true,
    "unknown_capture": true,
    "personnel_event": true,
    "prospect": true,
    "site_issue": true,
    "supply_need": true,
    "monthly_summary": true,
    "equipment_request": true,
    "supply_order": true,
    "plan": true,
    "inventory": true,
    "note": true,
    "operator": true
  };
  if (!newDoc.type || !canonicalTypes[newDoc.type]) {
    throw({forbidden: 'Document type must be one of the canonical entity types.'});
  }
  if (newDoc.type !== 'operator' && !newDoc.operator) {
    throw({forbidden: 'Non-operator entity documents require an operator field.'});
  }
}

by_type.map:
function(doc) {
  if (doc._deleted) return;
  emit([doc.type, doc._id], null);
}

by_operator_type.map:
function(doc) {
  if (doc._deleted) return;
  if (typeof doc.operator === 'undefined') return;
  emit([doc.operator, doc.type, doc._id], null);
}

employees_by_site.map:
function(doc) {
  if (doc._deleted) return;
  if (doc.type !== 'employee') return;
  var status = doc.status || null;
  var value = {name: doc.name || null, person_id: doc.person_id || null, hire_date: doc.hire_date || null};
  if (Array.isArray(doc.site_ids) && doc.site_ids.length > 0) {
    for (var i = 0; i < doc.site_ids.length; i++) {
      emit([doc.site_ids[i], status, doc._id], value);
    }
    return;
  }
  emit([null, status, doc._id], value);
}

employees_by_status.map:
function(doc) {
  if (doc._deleted) return;
  if (doc.type !== 'employee') return;
  var status = doc.status || null;
  emit([status, doc._id], {name: doc.name || null, person_id: doc.person_id || null, site_ids: doc.site_ids || [], hire_date: doc.hire_date || null});
}

visits_by_site_date.map:
function(doc) {
  if (doc._deleted) return;
  if (doc.type !== 'visit') return;
  var site_id = doc.site_id || doc.job || null;
  var date = doc.date || doc.visit_date || null;
  emit([site_id, date], {evidence: doc.evidence || doc.content || null, confidence: doc.confidence || null, visited_by: doc.visited_by || null, visit_type: doc.visit_type || null});
}

opportunities_by_site_status.map:
function(doc) {
  if (doc._deleted) return;
  if (doc.type !== 'opportunity') return;
  var site_id = doc.site_id || doc.job || null;
  var status = doc.status || null;
  emit([site_id, status, doc._id], {title: doc.title || doc.name || null});
}

issues_by_site_status.map:
function(doc) {
  if (doc._deleted) return;
  if (doc.type !== 'site_issue') return;
  var site_id = doc.site_id || doc.job || null;
  var status = doc.status || null;
  emit([site_id, status, doc._id], {title: doc.title || doc.name || null, category: doc.category || null, priority: doc.priority || null});
}

locations_all.map:
function(doc) {
  if (doc._deleted) return;
  if (doc.type !== 'location') return;
  var account = doc.account || null;
  var name = doc.name || doc.location || null;
  emit([account, name, doc._id], {site_id: doc.site_id || doc.job || null, account: account});
}
